/* Topic anchors for the listed 2019 SomaSem volumes and the identified
 * 2023 preschool / 2021 elementary Miracle Calculation publications.
 * Public contents headings identify topics, not the books' actual items,
 * operand limits, representations or solution methods. All questions are
 * independently generated by this app. */
(function () {
  'use strict';
  const W = typeof window !== 'undefined' ? window : globalThis;
  const catalog = W.NM_PLACEMENT_BOOKS;
  if (!catalog) throw new Error('Load placement-books.js before book-volume-topics.js');
  const rows = (catalogId, keys) => {
    const steps = catalog.getSteps(catalogId, '2019');
    return keys.map((refs, index) => ({ course: index + 1,
      topics: steps[index].topicSummary.ko, refs: refs.split(' ') }));
  };
  const add = (name, catalogId, before, keys, beforeBook) => {
    W[name] = { before, beforeBook, courses: rows(catalogId, keys) };
  };
  add('NM_SOMA_K_2019', 'soma-k', 'f-ten10', [
    'AD1@1 SB1@1', 'AD2@1 SB2@1', 'AD1@1 SB1@1', 'AD2@1 SB2@1',
    'AD1@1 SB1@1', 'AD2@1 SB2@1', 'AD2@1 SB2@1', 'NS2@1 NS2@2'
  ], { series: 'soma-p', course: 8 });
  W.NM_SOMA_K_2019.courses.forEach((row, index) => {
    row.maxNumber = [10, 20, 10, 20, 10, 20, 20, 7][index];
  });
  add('NM_SOMA_A_2019', 'soma-a', 'f-ten10', [
    'AD1@1 AD2@1', 'SB1@1 SB2@1', 'AD10@1', 'AD10@2 SB2@1',
    'AD3@1 AD3@2', 'SB3@1 SB3@2', 'AD5@1 AD5@2 SB4@1 SB4@2',
    'AD10@2 SB4@2'
  ], { series: 'soma-k', course: 8 });
  add('NM_SOMA_B_2019', 'soma-b', 'f-ten10', [
    'AD5@1 AD5@2 AD5@3', 'SB4@1 SB4@2', 'AD6@1 AD6@2 SB6@1 SB6@2',
    'AD6@2 SB6@2', 'ML1@1 ML1@2', 'ML2@3 ML3@3 ML4@1',
    'DV1@1 DV2@1', 'ML4@1 DV2@1 DV3@1'
  ], { series: 'soma-a', course: 8 });
  add('NM_SOMA_C_2019', 'soma-c', 'f-ten10', [
    'ML8@1 ML8@2', 'ML8@3 ML8@4 ML8@5', 'DV4@1 DV4@2',
    'DV5@1 DV5@2', 'ML9@1 ML9@2 ML9@3', 'DV5@3 DV5@5 DV5@6',
    'MX1@1 MX1@2', 'MX1@1 MX1@2 MX1@3'
  ], { series: 'soma-b', course: 8 });
  add('NM_SOMA_D_2019', 'soma-d', 'f-ten10', [
    'FR1@1 FR3@1', 'FR3@2 FR3@4', 'DC1@1 DC1@2 DC1@3',
    'DV7@1 DV7@2 DV7@3', 'FR4@1 FR4@2', 'FR4@1 FR4@2 FR5@1'
  ], { series: 'soma-c', course: 8 });

  const miracle = catalog.getSteps('miracle');
  const miracleRows = ids => ids.map((id, index) => {
    const step = miracle.find(candidate => candidate.id === id);
    if (!step || !step.coverage.length) throw new Error('Missing Miracle topic ' + id);
    return { course: index + 1, topics: step.label.ko.split(' — ')[1], refs: step.coverage.slice() };
  });
  W.NM_MIRACLE_PRE_2023 = { before: 'f-order10', courses:
    miracleRows([1, 2, 3, 4, 5].map(n => 'pre-2023-v' + n)) };
  W.NM_MIRACLE_ELEM_2021 = { before: 'f-ten10', courses:
    miracleRows(Array.from({ length: 12 }, (_, i) => 'elem-2021-v' + (i + 1))) };
})();
